rules:
// Sterownik VAV Nefryt wg layoutu (REGULACJA GLOWNA / NAWIEW / WYCIAG).
// p = odczyt biezacy, prev = poprzedni. Wymiary kanalow w METRACH (0,75 x 0,15).
const jest=k=>typeof p[k]==='number'&&isFinite(p[k]);
const tol=(a,b,proc,abs)=>Math.abs(a-b)<=Math.abs(a)*proc/100+(abs||1);
const A_sup=p.SupplyH*p.SupplyV;                 // m2
const A_ext=p.ReturnH*p.ReturnV;

// Przeplyw liczony z predkosci - tak liczy go sterownik (blok Multiply2):
// suma predkosci x przekroj x 3600.
const q_sup_calc=p.SpeedSupply*A_sup*3600;
const q_ext_calc=p.SpeedReturn*A_ext*3600;

// Przeplyw faktyczny: bierzemy z urzadzenia, a gdyby tego punktu nie bylo
// (inny wariant programu), spadamy na wartosc policzona z predkosci.
const q_sup=jest('FlowSupply')?p.FlowSupply:q_sup_calc;
const q_ext=jest('FlowReturn')?p.FlowReturn:q_ext_calc;

// Rampa CO2: od (nastawa - PropBand) do nastawy, z MinFlow do MaxFlow (LinearGraph, Limited)
const x1=p.CO2Setpoint-p.CO2PropBand;
const ramp=Math.min(1,Math.max(0,(p.CO2-x1)/(p.CO2PropBand||1)));
const sp_auto=p.MinFlow+ramp*(p.MaxFlow-p.MinFlow);

// Tryb (NumericSelect): 1-AUTO, 2-MIN, 3-MAX, 4-OFF
const m=Number(p.Mode);
const sp_sup=m===1?sp_auto:m===2?p.MinFlow:m===3?p.MaxFlow:0;
const sp_ext=sp_sup-p.Diff;                      // nastawa nadazna za nawiewem

// Regulacje oceniamy dopiero po ustabilizowaniu - przepustnica dojezdza do nowej
// nastawy kilkadziesiat sekund, inaczej ROZJAZD migalby caly czas.
const stoi=(a,b)=>tol(a,b,1,5);
// przeplyw poprzedni liczymy tak samo jak biezacy, inaczej przy braku punktu
// FlowSupply porownywalibysmy wartosc sama ze soba i wszystko udawaloby stan ustalony
const q_sup_prev=jest('FlowSupply')?prev.FlowSupply:prev.SpeedSupply*A_sup*3600;
const q_ext_prev=jest('FlowReturn')?prev.FlowReturn:prev.SpeedReturn*A_ext*3600;
const ustalone=stoi(q_sup,q_sup_prev)&&stoi(q_ext,q_ext_prev);
const kraniec=poz=>!jest('PositionSupply')?false:(poz>=99||poz<=1);
const pomin=poz=>!ustalone||kraniec(poz);

const r=[];

// Te dwie reguly sprawdzaja wlasny rachunek sterownika, wiec maja sens tylko
// wtedy, gdy urzadzenie podaje i predkosc, i przeplyw.
if(jest('FlowSupply')&&jest('SpeedSupply'))
 r.push(['przeplyw nawiewu = predkosc x przekroj x 3600', q_sup_calc, p.FlowSupply, tol(q_sup_calc,p.FlowSupply,3)]);
if(jest('FlowReturn')&&jest('SpeedReturn'))
 r.push(['przeplyw wyciagu = predkosc x przekroj x 3600', q_ext_calc, p.FlowReturn, tol(q_ext_calc,p.FlowReturn,3)]);

r.push(['nastawa nawiewu wg rampy CO2 i trybu', sp_sup, q_sup,
   pomin(p.PositionSupply)||tol(sp_sup,q_sup,10,20)]);
r.push(['wyciag nadaza za nawiewem (nawiew - DIFF)', sp_ext, q_ext,
   pomin(p.PositionReturn)||tol(sp_ext,q_ext,10,20)]);
r.push(['roznica nawiew-wyciag = DIFF', p.Diff, q_sup-q_ext,
   pomin(p.PositionSupply)||pomin(p.PositionReturn)||tol(p.Diff,q_sup-q_ext,10,25)]);

// Brakujace punkty zglaszamy wprost, zeby nie udawaly bledu regulacji.
const wymagane=['Mode','MinFlow','MaxFlow','CO2PropBand','CO2Setpoint','Diff',
                'SupplyH','SupplyV','ReturnH','ReturnV','CO2','SpeedSupply','SpeedReturn'];
const brak=wymagane.filter(k=>!jest(k));
if(brak.length) r.push(['BRAK PUNKTOW (sprawdz mapowanie): '+brak.join(', '), 0, brak.length, false]);

// Kontrole konfiguracji - lapia zla nastawe, nie regulacje.
if(p.SupplyH>10||p.SupplyV>10||p.ReturnH>10||p.ReturnV>10)
 r.push(['wymiary kanalu w METRACH (wpisano mm?)', 1, 0, false]);
if(p.MinFlow>=p.MaxFlow) r.push(['MinFlow < MaxFlow', 1, 0, false]);
if(p.CO2PropBand<=0) r.push(['PropBand > 0', 1, 0, false]);
if(m===4) r.push(['UWAGA: tryb OFF (4) - regulacja wylaczona', 1, 0, false]);
return r;
